import React, { useState } from 'react';
import SectionLabel from '../services/SectionLabel';

const TechStack = () => {
  const [activeFilter, setActiveFilter] = useState('all');

  const technologies = [
    { icon: "fab fa-html5", name: "HTML", color: "#E34F26", category: "frontend", level: 90 },
    { icon: "fab fa-css3-alt", name: "CSS", color: "#2983c4ff", category: "frontend", level: 85 },
    { icon: "devicon-sass-original", name: "SCSS", color: "#CC6699", category: "frontend", level: 80 },
    { icon: "fab fa-js-square", name: "JavaScript", color: "#F7DF1E", category: "frontend", level: 88 },
    { icon: "devicon-typescript-plain", name: "TypeScript", color: "#4085cfff", category: "frontend", level: 75 },
    { icon: "fab fa-react", name: "React", color: "#61DAFB", category: "frameworks", level: 92 },
    { icon: "fab fa-angular", name: "Angular", color: "#DD0031", category: "frameworks", level: 80 },
    { name: "Spring Boot", isIconify: true, iconifyIcon: "logos:spring-icon", category: "frameworks", level: 78 },
    { name: "Express", isIconify: true, iconifyIcon: "simple-icons:express", category: "frameworks", level: 75 },
    { name: "Flutter", isIconify: true, iconifyIcon: "logos:flutter", category: "frameworks", level: 70 },
    { name: "Dart", isIconify: true, iconifyIcon: "logos:dart", category: "frameworks", level: 70 },
    { icon: "fab fa-node", name: "Node.js", color: "#4CA54C", category: "backend", level: 85 },
    { name: "MySQL", isIconify: true, iconifyIcon: "simple-icons:mysql", color: "#ffffff", category: "backend", level: 80 },
    { icon: "fab fa-git-alt", name: "Git", color: "#F05032", category: "tools", level: 88 },
    { icon: "fab fa-figma", name: "Figma", color: "#F24E1E", category: "tools", level: 75 },
    { icon: "bi-kanban", name: "Trello", color: "#3390c5ff", category: "tools", level: 80 },
    { icon: "bi-graph-up", name: "Power BI", color: "#F2C811", category: "tools", level: 85 }
  ];

  const categories = [
    { key: 'all', label: 'Todos' },
    { key: 'frontend', label: 'Front-end' },
    { key: 'backend', label: 'Back-end' },
    { key: 'frameworks', label: 'Frameworks' },
    { key: 'tools', label: 'Ferramentas' }
  ];

  const filteredTechs = activeFilter === 'all' 
    ? technologies 
    : technologies.filter(tech => tech.category === activeFilter);

  const getCategoryIcon = (category) => {
    const icons = {
      frontend: 'bi-window',
      backend: 'bi-server',
      frameworks: 'bi-grid-3x3-gap-fill',
      tools: 'bi-tools'
    };
    return icons[category] || 'bi-code';
  };

  return (
    <section id="testimonials" className="testimonials section">
      <div className="section-glow"></div>
      <div className="section-waves"></div>
      <div className="section-orbs">
        <div className="orb orb-1"></div>
        <div className="orb orb-2"></div>
        <div className="orb orb-3"></div>
      </div>

      <div className="container">
        <SectionLabel sectionId="skills" />

        <div className="section-title" data-aos="fade-up">
          <h2 data-translate="tech_title">Hard Skills</h2>
          <div className="tech-counter">{technologies.length} tecnologias</div>
        </div>
      </div>

      <div className="container">
        <div className="tech-filters" data-aos="fade-up">
          {categories.map((cat) => (
            <button
              key={cat.key}
              className={`tech-filter-btn ${activeFilter === cat.key ? 'active' : ''}`}
              onClick={() => setActiveFilter(cat.key)}
            >
              {cat.label}
            </button>
          ))}
        </div>

        <div className="tech-grid-wrapper" data-aos="fade-up">
          {categories.map((cat) => {
            if (activeFilter !== 'all' && activeFilter !== cat.key) return null;
            
            const techs = activeFilter === 'all' 
              ? filteredTechs.filter(t => t.category === cat.key)
              : filteredTechs;

            if (techs.length === 0) return null;

            return (
              <div key={cat.key} className="tech-category">
                <div className="category-header">
                  <div className="category-icon-wrapper">
                    <i className={getCategoryIcon(cat.key)}></i>
                  </div>
                  <h3 className="category-title" data-translate={cat.key + '_title'}>
                    {cat.label}
                  </h3>
                  <span className="category-count">{techs.length}</span>
                </div>
                <div className="tech-grid">
                  {techs.map((tech, index) => (
                    <div key={`${cat.key}-${index}`} className="tech-card" data-tooltip={tech.name}>
                      <div className="tech-icon-wrapper">
                        {tech.isIconify ? (
                          <iconify-icon icon={tech.iconifyIcon} width="32" height="32"></iconify-icon>
                        ) : (
                          <i className={tech.icon} style={{ color: tech.color }}></i>
                        )}
                      </div>
                      <span className="tech-name">{tech.name}</span>
                      <div className="tech-level-bar">
                        <div 
                          className="tech-level-fill" 
                          style={{ width: `${tech.level}%` }}
                        ></div>
                      </div>
                      <span className="tech-level-text">{tech.level}%</span>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
};

export default TechStack;
